solutions.javascript:
const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const M = tok[0], q = tok[1];
const bit = new Array(M + 1).fill(0);
const out = [];
for (let i = 0; i < q; i++) {
  const t = tok[2 + 2 * i];
  let x = tok[3 + 2 * i];
  if (t === 1) {
    for (; x <= M; x += x & -x) bit[x]++;
  } else {
    let s = 0;
    for (; x > 0; x -= x & -x) s += bit[x];
    out.push(s);
  }
}
console.log(out.join("\n"));

