#include <bits/stdc++.h>
using namespace std;
int main() {
    int M, q;
    scanf("%d %d", &M, &q);
    vector<int> bit(M + 1, 0);
    while (q--) {
        int t, x;
        scanf("%d %d", &t, &x);
        if (t == 1) {
            for (; x <= M; x += x & -x) bit[x]++;
        } else {
            int s = 0;
            for (; x > 0; x -= x & -x) s += bit[x];
            printf("%d\n", s);
        }
    }
    return 0;
}
